function taskOpsSnapshot($db,string $p):array{$rows=$db->driver()==='mysql'?$db->query('SELECT TABLE_NAME name FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE()')->result_array():$db->query("SELECT name FROM sqlite_master WHERE type='table'")->result_array();$out=[];foreach($rows as$r){$t=$r['name'];if(!str_starts_with($t,$p))continue;$data=$db->query('SELECT * FROM '.$t)->result_array();usort($data,static fn($a,$b)=>strcmp(json_encode($a),json_encode($b)));$out[$t]=$data;}ksort($out);return$out;}
function taskOpsLate($db,string$p,string$table,string$condition,string$sql):void{if($db->driver()==='mysql'){$db->query('SET @task_ops_fault_hit=0');$db->query("CREATE TRIGGER {$p}task_ops_last AFTER INSERT ON {$p}{$table} FOR EACH ROW BEGIN IF $condition THEN SET @task_ops_fault_hit=COALESCE(@task_ops_fault_hit,0)+1; $sql; END IF; END");}else{$GLOBALS['taskOpsFaultHit']=0;$db->pdo->sqliteCreateFunction('task_ops_hit',function(){return ++$GLOBALS['taskOpsFaultHit'];},0);$db->query("CREATE TRIGGER {$p}task_ops_last AFTER INSERT ON {$p}{$table} WHEN $condition BEGIN SELECT task_ops_hit(); $sql; END");}}
function taskOpsHit($db):int{return$db->driver()==='mysql'?(int)$db->query('SELECT @task_ops_fault_hit hit')->row()->hit:$GLOBALS['taskOpsFaultHit'];}
